sys_script_include.script:
var IntegrationLogService = Class.create();

IntegrationLogService.prototype = {

    initialize: function() {
        this.validationUtils = new ValidationUtils();
    },

    /**
     * Check whether an Integration Log record exists.
     *
     * @param {String} integrationSysId
     * @return {Boolean}
     */
    integrationExists: function(integrationSysId) {

        if (this.validationUtils.isEmpty(integrationSysId)) {
            return false;
        }

        var integration = new GlideRecord(
            'x_2130921_caresy_0_integration_log'
        );

        if (!integration.isValid()) {
            gs.error(
                'IntegrationLogService: Integration Log table is invalid.'
            );
            return false;
        }

        return integration.get(integrationSysId);
    },

    /**
     * Retrieve an Integration Log record.
     *
     * @param {String} integrationSysId
     * @return {GlideRecord|null}
     */
    getIntegration: function(integrationSysId) {

        if (this.validationUtils.isEmpty(integrationSysId)) {
            return null;
        }

        var integration = new GlideRecord(
            'x_2130921_caresy_0_integration_log'
        );

        if (!integration.isValid()) {
            gs.error(
                'IntegrationLogService: Integration Log table is invalid.'
            );
            return null;
        }

        if (integration.get(integrationSysId)) {
            return integration;
        }

        return null;
    },

    /**
     * Check whether an Integration Log record is active.
     *
     * @param {String} integrationSysId
     * @return {Boolean}
     */
    isIntegrationActive: function(integrationSysId) {

        var integration = this.getIntegration(integrationSysId);

        if (!integration) {
            return false;
        }

        return integration.getValue('active') == '1';
    },

    type: 'IntegrationLogService'
};
